import AppKit

/// Monochrome brand marks for programs a pane may be running, from Simple
/// Icons (CC0, https://simpleicons.org, v16.35.0). Drawn as template images
/// tinted with the brand colour (nil = the text colour, for black marks).
enum BrandIcon: String, CaseIterable {
    case claude, openai, gemini, node, bun, deno, python, git, docker, kubernetes, vim, neovim, rust, go, postgres, mysql, redis

    /// sRGB hex, or nil to follow the text colour.
    var hex: UInt32? {
        switch self {
        case .claude: return 0xD97757
        case .openai: return nil
        case .gemini: return 0x8E75B2
        case .node: return 0x5FA04E
        case .bun: return nil
        case .deno: return nil
        case .python: return 0x3776AB
        case .git: return 0xF03C2E
        case .docker: return 0x2496ED
        case .kubernetes: return 0x326CE5
        case .vim: return 0x019733
        case .neovim: return 0x57A143
        case .rust: return nil
        case .go: return 0x00ADD8
        case .postgres: return 0x4169E1
        case .mysql: return 0x4479A1
        case .redis: return 0xFF4438
        }
    }

    @MainActor private static var cache: [BrandIcon: NSImage] = [:]

    @MainActor var image: NSImage? {
        if let hit = Self.cache[self] { return hit }
        guard let img = NSImage(data: Data(svg.utf8)) else { return nil }
        img.isTemplate = true
        Self.cache[self] = img
        return img
    }

